import json,shutil
from pathlib import Path
root=Path('dist'); d=json.loads((root/'data.json').read_text()); fixture=json.loads(json.dumps(d)); fixture['topics']=[];fixture['relations']=[]
for i,state in enumerate(['known','unknown','pending','not_applicable']):
 t=json.loads(json.dumps(d['topics'][7]));t['id']='QA'+str(i);t['name']=['已知零值','缺少原理評分','尚待評估','不適用示例'][i];t['scores']['P'].update(status=state,value=0 if state=='known' else None,reason='僅供測試，不進入正式資料。');t['scores']['M']['value']=0;fixture['topics'].append(t)
multi=json.loads(json.dumps(d)); extra=dict(d['relations'][0]); extra.update(id='QA-multi',from_='K39',to='K03',condition='QA only: additional editorial parent'); extra['from']=extra.pop('from_'); multi['relations'].append(extra)
reverse=json.loads(json.dumps(d)); extra=dict(d['relations'][0]); extra.update(id='QA-reverse',from_='K25',to='K27',kind='使用或涉及',condition='QA only: opposite direction'); extra['from']=extra.pop('from_'); reverse['relations'].append(extra)
for name,blob in [('qa-import',d),('qa-reverse',reverse),('qa-multi',multi),('qa-fixture',fixture),('qa-invalid',{'schemaVersion':999,'topics':[],'relations':[],'sources':[]})]:
 p=root/name;p.mkdir(exist_ok=True)
 for f in ['index.html','app.mjs','coordinate-motion.mjs','map-layout.mjs','core.mjs','hierarchy.mjs','navigator.mjs','relation-style.mjs','legend.mjs','exploration-history.mjs','data-transfer.mjs','data-manager.mjs','style.css']:shutil.copy(root/f,p/f)
 (p/'data.json').write_text(json.dumps(blob,ensure_ascii=False))
(root/'qa.html').write_text('''<!doctype html><html><head><meta charset="utf-8"><title>QA viewport harness</title></head><body style="margin:0;background:#ddd;font:14px sans-serif"><div style="height:45px;padding:5px;box-sizing:border-box">Viewport <select id="size"><option>1440x900</option><option>390x844</option><option>320x740</option><option>768x1024</option><option>844x390</option><option>1024x768</option></select> Scenario <select id="scenario"><option value="./">48 topics</option><option value="qa-import/index.html">Data import workspace</option><option value="qa-fixture/index.html">Zero / unknown / pending / N/A</option><option value="qa-invalid/index.html">Invalid data</option><option value="qa-multi/index.html">Multiple collection routes</option><option value="qa-reverse/index.html">Opposite direction / parallel edges</option></select></div><iframe title="Test viewport" id="preview" src="./" style="border:0;display:block;transform-origin:top left;background:white"></iframe><script>const f=document.getElementById('preview'),s=document.getElementById('size'),c=document.getElementById('scenario');function resize(){const [w,h]=s.value.split('x').map(Number);f.style.width=w+'px';f.style.height=h+'px';f.style.transform='scale('+Math.min((innerWidth-10)/w,(innerHeight-50)/h,1)+')';}s.onchange=resize;c.onchange=()=>{f.src=c.value};onresize=resize;resize();
const report=document.createElement('output');report.id='motion-report';report.style.cssText='display:block;font-size:11px;position:fixed;right:8px;bottom:5px;background:#fff;max-width:500px;z-index:2';document.body.append(report);
f.addEventListener('load',()=>{const doc=f.contentDocument;let samples=[],sampling=false;const sample=()=>{const svg=doc.querySelector('#plot');if(!svg)return;const nodes=[...svg.querySelectorAll('[data-area="coordinates"],[data-area="outside"]')];samples.push({time:performance.now(),count:new Set([...nodes.map(n=>n.dataset.nodeId),...doc.querySelectorAll('#outer-points button')].map(n=>typeof n==='string'?n:n.dataset.topic)).size,point:nodes.find(n=>n.dataset.nodeId==='K39')?.getAttribute('transform'),company:nodes.find(n=>n.dataset.nodeId==='K45')?.getAttribute('transform')});if(svg.getAttribute('aria-busy')==='true'){requestAnimationFrame(sample);}else{sampling=false;report.textContent=JSON.stringify({frames:samples.length,duration:Math.round(samples.at(-1).time-samples[0].time),minimumPoints:Math.min(...samples.map(s=>s.count)),distinctPositions:new Set(samples.map(s=>s.point)).size,companyPositions:new Set(samples.map(s=>s.company)).size,first:samples[0].point,last:samples.at(-1).point});}};new MutationObserver(()=>{if(!sampling&&doc.querySelector('#plot')?.getAttribute('aria-busy')==='true'){sampling=true;samples=[];requestAnimationFrame(sample);}}).observe(doc,{subtree:true,attributes:true,attributeFilter:['aria-busy']});});
</script></body></html>''')
